import{_ as e,o as a,c as i,a0 as t}from"./chunks/framework.B6reNh8h.js";const k=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),n={name:"reference/cli.md"};function o(p,s,h,d,l,r){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Visualization host for the 9aia tool suite</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: pavo [COMMAND]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  drivers     List discovered tamias-driver-* executables that speak pavo</span></span>
<span class="line"><span>  views       List every &lt;driver&gt;:&lt;view&gt; ref with title/route</span></span>
<span class="line"><span>  chrome      Show the merged contribution slots</span></span>
<span class="line"><span>  view        Resolve a deep link and render it</span></span>
<span class="line"><span>  query       Raw query-op passthrough to a driver</span></span>
<span class="line"><span>  submit      Submit a form&#39;s field values (submit wire op)</span></span>
<span class="line"><span>  jobs        List the aggregated job feed (contributes.jobs providers)</span></span>
<span class="line"><span>  notifications  List the aggregated notification feed</span></span>
<span class="line"><span>  serve       Run the localhost HTTP bridge for the web host</span></span>
<span class="line"><span>  open        Hand off to pavo-tui (falls back to \`view\` text off-TTY)</span></span>
<span class="line"><span>  manifest    Print the machine-readable capability manifest</span></span>
<span class="line"><span>  schema      Print the verb schema</span></span>
<span class="line"><span>  help        Print this message or the help of the given subcommand(s)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -h, --help     Print help</span></span>
<span class="line"><span>  -V, --version  Print version</span></span></code></pre></div><p><code>--json</code> is a per-subcommand flag on the listing/query verbs; <code>view --format json</code> is its machine-readable mode. Errors go to stderr; exit codes are CI-meaningful: <code>0</code> ok, <code>1</code> view/driver error, <code>2</code> usage.</p><h2 id="drivers" tabindex="-1">drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;drivers&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>Lists every discovered <code>tamias-driver-*</code> that speaks pavo — name, title, version, view count, renderer count, contributes summary. Discovery scans <code>PATH</code> and <code>&lt;tamias-home&gt;/drivers/</code> (<code>$TAMIAS_HOME</code> → <code>$XDG_DATA_HOME/tamias</code> → <code>~/.local/share/tamias</code> → <code>./.tamias</code>).</p><h2 id="views" tabindex="-1">views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;views&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> views</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--driver </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>Every view as a <code>&lt;driver&gt;:&lt;view&gt;</code> ref with title, route, and query names. <code>--driver</code> filters to one driver.</p><h2 id="chrome" tabindex="-1">chrome <a class="header-anchor" href="#chrome" aria-label="Permalink to &quot;chrome&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chrome</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>The merged contribution slots — all eight built-ins: <code>navbar</code>, <code>dashboard</code>, <code>statusbar</code>, <code>routes</code>, <code>sidebar</code>, <code>headerActions</code>, <code>notifications</code>, <code>jobs</code> — plus forward-compat <code>extra</code> slots, resolved across all drivers by priority. The <code>notifications</code>/<code>jobs</code> entries are provider display metadata; the feed <em>data</em> is what <code>pavo jobs</code> / <code>pavo notifications</code> aggregate.</p><h2 id="view" tabindex="-1">view <a class="header-anchor" href="#view" aria-label="Permalink to &quot;view&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">drive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--param </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">k=v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> …]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--format </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FMT]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>Resolves the deep link and renders the ViewNode tree plus bound data.</p><table tabindex="0"><thead><tr><th><code>--format</code></th><th>Output</th></tr></thead><tbody><tr><td><code>text</code> (default)</td><td>summary of the tree + bound data</td></tr><tr><td><code>json</code></td><td>raw <code>ViewResult</code></td></tr><tr><td><code>dot</code></td><td>graph nodes → graphviz</td></tr><tr><td><code>mermaid</code></td><td>graph nodes → mermaid</td></tr><tr><td><code>&lt;plugin&gt;</code></td><td>any format a renderer plugin claims (e.g. <code>svg</code>, <code>ascii</code>)</td></tr></tbody></table><p>Renderer plugins take precedence per node: a plugin listing a built-in format name (<code>text</code>/<code>dot</code>/<code>mermaid</code>) in <code>renderers[].surfaces.cli.formats</code> overrides it for the kinds it claims; unclaimed nodes keep the built-in output. <code>json</code> is host-owned and never routed to plugins.</p><p><code>--param k=v</code> merges caller params into every query binding; repeatable, values parse as JSON when possible. <code>--json</code> prints the machine-readable envelope.</p><h2 id="query" tabindex="-1">query <a class="header-anchor" href="#query" aria-label="Permalink to &quot;query&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">drive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">quer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--param </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">k=v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> …]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>Raw <code>query</code> op passthrough — <code>{&quot;op&quot;:&quot;query&quot;,&quot;query&quot;:&quot;&lt;query&gt;&quot;, &quot;params&quot;:{…}}</code> — for probing a driver&#39;s data without a view.</p><h2 id="submit" tabindex="-1">submit <a class="header-anchor" href="#submit" aria-label="Permalink to &quot;submit&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">drive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--form </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--param </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">k=v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> …]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>Sends the <code>submit</code> wire op — the form-interaction verb — with the given field values (<code>--param key=value</code>, repeatable; values parse as JSON when possible). <code>--form</code> picks a specific form node when the view carries several. Prints the driver&#39;s <code>SubmitResult</code> message and data; per-field validation <code>errors</code> exit 1 so CI can gate on them. <code>--json</code> dumps the full <code>SubmitResult</code> (including any updated <code>view</code>). Example: <code>pavo submit config:edit --param key=myco.theme --param value=dark</code>.</p><h2 id="jobs" tabindex="-1">jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;jobs&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>The aggregated job feed: <code>{&quot;op&quot;:&quot;jobs&quot;}</code> fanned out to every driver whose manifest declares <code>contributes.jobs</code>, each item flattened with <code>driver</code>/<code>driver_title</code> attribution. Per-driver failures are skipped, never fatal. Item shape: <code>JobItem</code> — see <a href="/pavo/reference/wire-ops.html#types">Wire ops → Types</a>.</p><h2 id="notifications" tabindex="-1">notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;notifications&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notifications</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--json]</span></span></code></pre></div><p>The aggregated notification feed — same pattern as <code>jobs</code> over the <code>notifications</code> wire op and <code>contributes.notifications</code> providers. <code>NotificationItem.read</code> is display-only in v1 (no write path).</p><h2 id="serve" tabindex="-1">serve <a class="header-anchor" href="#serve" aria-label="Permalink to &quot;serve&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--port </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">N]</span></span></code></pre></div><p>The localhost HTTP bridge (<code>127.0.0.1</code>; <code>--port 0</code> picks a free port). First stdout line is <code>listening http://127.0.0.1:&lt;port&gt;</code>. Endpoints and static serving: <a href="/pavo/how-to/serve-web.html">Serve the web surface</a>.</p><h2 id="open" tabindex="-1">open <a class="header-anchor" href="#open" aria-label="Permalink to &quot;open&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;driver&gt;:&lt;view&gt;]</span></span></code></pre></div><p>Hands off to <code>pavo-tui</code> with the deep link, or the bare dashboard when no target is given. On a non-TTY it falls back to <code>pavo view</code> text output.</p><h2 id="manifest-schema" tabindex="-1">manifest / schema <a class="header-anchor" href="#manifest-schema" aria-label="Permalink to &quot;manifest / schema&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the CLI&#39;s own capability manifest (sibling convention)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # the verb schema</span></span></code></pre></div>`,38)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
